#include "Editor.h"
#include "Graph.h"
namespace cygame {
void EditorApp::recordTypeRename(const std::string& from,const std::string& to){
    bool found=false;for(auto& [origin,next]:typeRenames_.items())if(next==from){next=to;found=true;}
    const auto id=std::string(typeKind_?"struct.":"enum.")+typeName_;const auto library=core.graphs().at(activeGraph_).value("types",Json::object());
    if(!found&&library.contains(id)){const auto& d=library.at(id);bool original=typeKind_?d.at("fields").contains(from):std::find(d.at("members").begin(),d.at("members").end(),Json(from))!=d.at("members").end();if(original)typeRenames_[from]=to;}
}
void EditorApp::graphTypesUI(){
    const auto owner=core.graphs().at(activeGraph_);if(owner.at("domain")!="logic")return;const auto types=owner.value("types",Json::object());cyui::sectionTitle(tr("Data types"));
    if(cyui::ghostButton(tr("New data type"))){typeRenames_=Json::object();typeEditing_=false;typeKind_=0;std::snprintf(typeName_,sizeof(typeName_),"NewType");typeDraft_={{"kind","enum"},{"members",{"First","Second"}},{"default","First"}};ImGui::OpenPopup("##dataTypeDefinition");}probeInterface("types/new");
    for(const auto& [id,d]:types.items()){
        if(!matches(id,myGraphSearch_))continue;ImGui::PushID(id.c_str());cyui::textDim("%s",id.c_str());
        if(cyui::ghostButton(tr("Edit"))){typeRenames_=Json::object();typeEditing_=true;typeKind_=d.at("kind")=="enum"?0:1;std::snprintf(typeName_,sizeof(typeName_),"%s",id.substr(id.find('.')+1).c_str());typeDraft_=d;typePopup_=true;}
        ImGui::SameLine();if(cyui::ghostButton(tr("Remove type")))invoke("graph_type_remove",{{"graphId",activeGraph_},{"typeId",id}});
        auto add=[&](const char* op,const char* title){if(cyui::ghostButton(tr(title))){Json p={{"graphId",activeGraph_},{"type",op},{"typeRef",id},{"position",{180,180}}};if(!activeFunction_.empty())p["functionName"]=activeFunction_;invoke("graph_node_add",p);}};
        add("typed.literal","Literal");ImGui::SameLine();if(d.at("kind")=="enum"){add("enum.to_string","To string");if(activeFunction_.empty()||owner["functions"][activeFunction_].value("mode","pure")=="execution")add("enum.switch","Switch on enum");}else{add("struct.make","Make structure");add("struct.break","Break structure");}ImGui::PopID();
    }
    if(typePopup_){ImGui::OpenPopup("##dataTypeDefinition");typePopup_=false;}
    if(ImGui::BeginPopup("##dataTypeDefinition")){
        {cyui::ScopedDisabled disabled(typeEditing_);ImGui::InputText(tr("Name"),typeName_,sizeof(typeName_));const char* kinds[]={tr("Enumeration"),tr("Structure")};if(ImGui::BeginCombo(tr("Kind"),kinds[typeKind_])){for(int k=0;k<2;++k){if(ImGui::Selectable(kinds[k],k==typeKind_)){typeKind_=k;typeDraft_=typeKind_?Json{{"kind","struct"},{"fields",{{"Value",{{"type","float"},{"default",0.}}}}}}:Json{{"kind","enum"},{"members",{"First","Second"}},{"default","First"}};}probeInterface(k?"types/kind/struct":"types/kind/enum");}ImGui::EndCombo();}probeInterface("types/kind");}
        if(typeKind_==0){int remove=-1;for(size_t i=0;i<typeDraft_["members"].size();++i){ImGui::PushID(int(i));char member[65]{};std::snprintf(member,sizeof(member),"%s",typeDraft_["members"][i].get_ref<const std::string&>().c_str());if(ImGui::InputText("##enumMember",member,sizeof(member))){const std::string old=typeDraft_["members"][i];recordTypeRename(old,member);if(typeDraft_["default"]==old)typeDraft_["default"]=std::string(member);typeDraft_["members"][i]=std::string(member);}ImGui::SameLine();if(cyui::ghostButton(tr("Remove")))remove=int(i);ImGui::PopID();}if(remove>=0){const auto removed=typeDraft_["members"][remove];for(auto it=typeRenames_.begin();it!=typeRenames_.end();)if(it.value()==removed)it=typeRenames_.erase(it);else ++it;typeDraft_["members"].erase(typeDraft_["members"].begin()+remove);}if(cyui::ghostButton(tr("Add member"))){std::string member="NewMember";for(int i=1;std::find(typeDraft_["members"].begin(),typeDraft_["members"].end(),Json(member))!=typeDraft_["members"].end();++i)member="NewMember"+std::to_string(i);typeDraft_["members"].push_back(member);}
            if(ImGui::BeginCombo(tr("Default member"),typeDraft_["default"].get_ref<const std::string&>().c_str())){for(const auto& m:typeDraft_["members"])if(ImGui::Selectable(m.get_ref<const std::string&>().c_str(),m==typeDraft_["default"]))typeDraft_["default"]=m;ImGui::EndCombo();}
        }else{
            const auto names=blueprintTypes(types);std::vector<const char*> labels;for(const auto& t:names)labels.push_back(t.c_str());std::string remove;
            for(auto& [name,field]:typeDraft_["fields"].items()){ImGui::PushID(name.c_str());cyui::sectionTitle(name.c_str());int index=0;for(size_t i=0;i<names.size();++i)if(field["type"]==names[i])index=int(i);ImGui::SetNextItemWidth(cyui::dp(260));if(ImGui::Combo("##fieldType",&index,labels.data(),int(labels.size()))){field["type"]=names[index];field["default"]=graphDefaultValue(names[index],types);}Json next;const std::string fieldType=field["type"];if(isNamedGraphType(fieldType)&&!types.contains(fieldType))cyui::textDim("%s",tr("Draft type unavailable; choose a type or reload."));else if(editValue("typeDraft/"+name,graphWidget(fieldType,types),field["default"],next))field["default"]=next;if(cyui::ghostButton(tr("Remove field")))remove=name;ImGui::PopID();}
            if(!remove.empty()){typeDraft_["fields"].erase(remove);for(auto it=typeRenames_.begin();it!=typeRenames_.end();)if(it.value()==remove)it=typeRenames_.erase(it);else ++it;}ImGui::InputText(tr("Field name"),typeField_,sizeof(typeField_));if(cyui::ghostButton(tr("Add field"))&&!typeDraft_["fields"].contains(typeField_))typeDraft_["fields"][typeField_]={{"type","float"},{"default",0.}};
        }
        if(typeEditing_&&typeKind_==1){cyui::sectionTitle(tr("Rename structure field"));std::vector<std::string> fields;for(const auto& [name,spec]:typeDraft_["fields"].items())fields.push_back(name);if(!fields.empty()){typeRenameIndex_=std::clamp(typeRenameIndex_,0,int(fields.size())-1);if(cyui::beginProperties("##fieldRename")){cyui::property(tr("Field"));if(ImGui::BeginCombo("##from",fields[typeRenameIndex_].c_str())){for(int i=0;i<int(fields.size());++i)if(ImGui::Selectable(fields[i].c_str(),i==typeRenameIndex_))typeRenameIndex_=i;ImGui::EndCombo();}cyui::property(tr("New field name"));ImGui::InputText("##to",typeRename_,sizeof(typeRename_));cyui::endProperties();}if(cyui::ghostButton(tr("Rename draft field"))){const auto old=fields[typeRenameIndex_];const std::string next=typeRename_;if(!next.empty()&&!typeDraft_["fields"].contains(next)){const auto field=typeDraft_["fields"][old];typeDraft_["fields"].erase(old);typeDraft_["fields"][next]=field;recordTypeRename(old,next);}}}}
        if(typeEditing_&&cyui::ghostButton(tr("Preview type migration"))){const auto id=std::string(typeKind_?"struct.":"enum.")+typeName_;auto result=previewTypeMigration({{"graphId",activeGraph_},{"typeId",id},{"definition",typeDraft_},{"renames",typeRenames_}});if(!result.contains("error"))ImGui::CloseCurrentPopup();}
        ImGui::TextWrapped("%s",tr("Changes must keep all existing values and pins valid. Referenced types cannot be removed."));
        if(cyui::primaryButton(tr("Apply data type"))){const std::string id=std::string(typeKind_?"struct.":"enum.")+typeName_;auto result=invoke("graph_type_define",{{"graphId",activeGraph_},{"typeId",id},{"definition",typeDraft_}});if(!result.contains("error"))ImGui::CloseCurrentPopup();}probeInterface("types/apply");ImGui::EndPopup();
    }
}
}
